const items = $input.all();

return items.map(inputItem => {
  const item = inputItem.json;

  const libraryId =
    item.adArchiveId ||
    item.adArchiveID ||
    null;

  const pageName =
    item.pageName ||
    item.snapshot?.pageName ||
    null;

  const fbPageId =
    item.pageId ||
    item.pageID ||
    item.snapshot?.pageId ||
    null;

  const followerCount =
    item.snapshot?.pageLikeCount != null
      ? Number(item.snapshot.pageLikeCount)
      : null;

  const category =
    Array.isArray(item.snapshot?.pageCategories)
      ? item.snapshot.pageCategories.join(', ')
      : item.snapshot?.pageCategories || null;

  let startedRunningOn = null;
  let longevityDays = null;

  if (item.startDate) {
    const startedDate = new Date(Number(item.startDate) * 1000);

    if (!isNaN(startedDate.getTime())) {
      startedRunningOn = startedDate.toISOString().split('T')[0];

      const today = new Date();
      const diffTime = today.getTime() - startedDate.getTime();

      longevityDays = Math.max(
        1,
        Math.ceil(diffTime / (1000 * 60 * 60 * 24))
      );
    }
  }

  const isActive =
    item.isActive !== undefined
      ? Boolean(item.isActive)
      : null;

  const platforms =
    item.publisherPlatform || null;

  const firstCard =
    Array.isArray(item.snapshot?.cards) &&
    item.snapshot.cards.length > 0
      ? item.snapshot.cards[0]
      : null;

  const rawText =
    firstCard?.body ||
    item.snapshot?.body?.text ||
    null;

  const cta =
    firstCard?.ctaText ||
    item.snapshot?.ctaText ||
    item.snapshot?.ctaType ||
    null;

  const creativeUrl =
    firstCard?.resizedImageUrl ||
    firstCard?.originalImageUrl ||
    firstCard?.videoPreviewImageUrl ||
    item.snapshot?.images?.[0]?.resizedImageUrl ||
    item.snapshot?.images?.[0]?.originalImageUrl ||
    item.snapshot?.videos?.[0]?.videoPreviewImageUrl ||
    null;

  const hasVideo =
    Array.isArray(item.snapshot?.videos) &&
    item.snapshot.videos.length > 0;

  const hasVideoCard =
    Boolean(firstCard?.videoHdUrl || firstCard?.videoSdUrl);

  const creativeType =
    hasVideo || hasVideoCard
      ? 'video'
      : creativeUrl
        ? 'image'
        : null;

  const hasMultipleVersions =
    item.collationCount != null
      ? Number(item.collationCount) > 1
      : false;

  return {
    json: {
      library_id: libraryId,
      page_name: pageName,
      fb_page_id: fbPageId,
      follower_count: followerCount,
      category,
      started_running_on: startedRunningOn,
      longevity_days: longevityDays,
      is_active: isActive,
      has_multiple_versions: hasMultipleVersions,
      platforms,
      creative_url: creativeUrl,
      creative_type: creativeType,
      raw_text: rawText,
      cta: cta,
      raw_snapshot: item
    }
  };
});

