const items = $input.all();
// Items come back from Gemini in the same order they were sent (1:1),
// so take the ad fields from the If node's true branch by index.
const ads = $('If').all();

return items.map((item, i) => {
  const orig = (ads[i] && ads[i].json) ? ads[i].json : {};
  const data = item.json;

  // Gemini call failed for this ad: keep the ad, flag it, invent nothing.
  if (data.error || data.errorMessage || data.errorType || data.statusCode >= 400) {
    return { json: { ...orig, parse_error: true, parse_error_message: 'Gemini extract call failed' } };
  }

  const rawText = data.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  if (!rawText || typeof rawText !== 'string') {
    return { json: { ...orig, parse_error: true, parse_error_message: 'Empty Gemini response' } };
  }

  try {
    const cleaned = rawText.trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();
    const parsed = JSON.parse(cleaned);
    return { json: { ...orig, ...parsed, parse_error: false } };
  } catch (error) {
    return { json: { ...orig, parse_error: true, parse_error_message: error.message } };
  }
});

