const geminiItems = $input.all();
const parseItems = $('Parse Extracted JSON').all();

const scored = [];

for (let i = 0; i < geminiItems.length; i++) {
  const adData = parseItems[i] ? parseItems[i].json : {};

  // Skip ads that failed extraction/parsing.
  // Do not create fake scores or zeros.
  if (adData.parse_error) {
    continue;
  }

  // Parse the Gemini creative-score response.
  let scoreJson;

  try {
    const text =
      geminiItems[i].json.candidates[0].content.parts[0].text;

    scoreJson = JSON.parse(text);
  } catch (e) {
    // If Gemini returned an invalid/missing score response,
    // skip this ad instead of inventing scores.
    continue;
  }

  // Extract the five Gemini scores.
  const hookScore = Number(scoreJson.hook_score);
  const clarityScore = Number(scoreJson.clarity_score);
  const ctaStrengthScore = Number(scoreJson.cta_strength_score);
  const visualAppealScore = Number(scoreJson.visual_appeal_score);
  const offerStrengthScore = Number(scoreJson.offer_strength_score);

  const subScores = [
    hookScore,
    clarityScore,
    ctaStrengthScore,
    visualAppealScore,
    offerStrengthScore
  ];

  // Skip if any required score is invalid.
  if (subScores.some((score) => !Number.isFinite(score))) {
    continue;
  }

  // ---------------------------------------------------------
  // 1. CREATIVE QUALITY
  // Average of the five 0-10 Gemini scores,
  // then normalize to 0-1.
  // ---------------------------------------------------------

  const creativeAverage =
    (
      hookScore +
      clarityScore +
      ctaStrengthScore +
      visualAppealScore +
      offerStrengthScore
    ) / 5;

  const creativeNorm = Math.max(
    0,
    Math.min(creativeAverage / 10, 1)
  );

  // ---------------------------------------------------------
  // 2. LONGEVITY
  // 90 days = maximum normalized longevity of 1.
  // ---------------------------------------------------------

  const days = Number(adData.longevity_days);

  const longevityNorm = Number.isFinite(days)
    ? Math.max(0, Math.min(days / 90, 1))
    : 0;

  // ---------------------------------------------------------
  // 3. ITERATION
  // Prefer Apify collationCount when available.
  //
  // 1 version  -> 0
  // 5+ versions -> 1
  //
  // If collationCount is unavailable, fall back to
  // has_multiple_versions.
  // ---------------------------------------------------------

  const rawSnapshot = adData.raw_snapshot || {};

  const versionCount =
    rawSnapshot.collationCount != null &&
    Number.isFinite(Number(rawSnapshot.collationCount))
      ? Number(rawSnapshot.collationCount)
      : null;

  let iterationNorm;

  if (versionCount != null) {
    iterationNorm = Math.max(
      0,
      Math.min((versionCount - 1) / 4, 1)
    );
  } else {
    iterationNorm = adData.has_multiple_versions ? 1 : 0;
  }

  // ---------------------------------------------------------
  // 4. COMPOSITE PROXY SCORE
  //
  // All three components are now on the SAME 0-1 scale.
  //
  // Creative Quality = 40%
  // Longevity        = 35%
  // Iteration        = 25%
  // ---------------------------------------------------------

  const compositeScore = Number(
    (
      0.40 * creativeNorm +
      0.35 * longevityNorm +
      0.25 * iterationNorm
    ).toFixed(4)
  );

  // ---------------------------------------------------------
  // OUTPUT
  // ---------------------------------------------------------

  scored.push({
    json: {
      ...adData,

      // Original Gemini 0-10 scores
      hook_score: hookScore,
      clarity_score: clarityScore,
      cta_strength_score: ctaStrengthScore,
      visual_appeal_score: visualAppealScore,
      offer_strength_score: offerStrengthScore,

      // Normalized 0-1 components
      creative_quality_score: Number(
        creativeNorm.toFixed(4)
      ),

      longevity_score: Number(
        longevityNorm.toFixed(4)
      ),

      iteration_score: Number(
        iterationNorm.toFixed(4)
      ),

      // Actual Apify version count when available
      version_count: versionCount,

      // Final 0-1 proxy score
      composite_score: compositeScore,

      // Gemini rationale
      analysis_notes: scoreJson.analysis_notes
    }
  });
}

return scored;

