const embeddings = $input.all();
const ads = $('Compute Composite Proxy Score').all();

if (embeddings.length !== ads.length) {
  throw new Error(
    `Embedding count mismatch: received ${embeddings.length} embeddings for ${ads.length} ads`
  );
}

const out = [];

for (let i = 0; i < embeddings.length; i++) {
  const values = embeddings[i].json.embedding?.values;

  if (!Array.isArray(values)) {
    throw new Error(
      `Ad ${i + 1}: Gemini response does not contain embedding.values`
    );
  }

  if (values.length !== 768) {
    throw new Error(
      `Ad ${i + 1}: expected 768 embedding dimensions, got ${values.length}`
    );
  }

  const ad = ads[i].json;

  out.push({
    json: {
      ...ad,
      embedding_values: values,
      embedding_content:
        'MySivi Ad: ' +
        (ad.hook || '') +
        ' - ' +
        (ad.analysis_notes || ''),
      embedding_dimension: values.length,
      embedding_verified: true
    }
  });
}

return out;

