// Report real run statistics only.
// Do not add impressions, CTR, spend, ROAS, or conversion data.

const parseItems = $('Parse Extracted JSON').all();
const scoredItems = $('Compute Composite Proxy Score').all();

const totalProcessed = parseItems.length;
const scoredCount = scoredItems.length;
const adsFailed = totalProcessed - scoredCount;

let topAd = null;

for (const item of scoredItems) {
  const ad = item.json;

  if (
    topAd === null ||
    Number(ad.composite_score) > Number(topAd.composite_score)
  ) {
    topAd = ad;
  }
}

return [
  {
    json: {
      total_ads_processed: totalProcessed,
      ads_failed: adsFailed,
      top_ranked_ad: topAd
        ? {
            library_id: topAd.library_id,
            page_name: topAd.page_name,
            hook: topAd.hook,
            composite_score: topAd.composite_score
          }
        : null
    }
  }
];
